import numpy as np
import matplotlib.pyplot as plt
import time
import warnings

from sklearn import cluster, mixture
from sklearn.neighbors import kneighbors_graph
from sklearn.preprocessing import StandardScaler
from sklearn.datasets import make_circles, make_moons, make_blobs, make_classification

# Try to import HDBSCAN, skip if not available
try:
    import hdbscan
    has_hdbscan = True
except ImportError:
    has_hdbscan = False

# Generate datasets
n_samples = 1500
random_state = 170

datasets = [
    (
        make_circles(n_samples=n_samples, factor=0.5, noise=0.05),
        "Noisy Circles"
    ),
    (
        make_moons(n_samples=n_samples, noise=0.05),
        "Noisy Moons"
    ),
    (
        make_blobs(n_samples=n_samples, random_state=8),
        "Blobs"
    ),
    (
        (StandardScaler().fit_transform(
            make_blobs(n_samples=n_samples, random_state=random_state)[0]
            @ [[0.6, -0.6], [-0.4, 0.8]]
        ), None),
        "Anisotropic Blobs"
    ),
    (
        make_blobs(
            n_samples=n_samples,
            cluster_std=[1.0, 2.5, 0.5],
            random_state=random_state
        ),
        "Varied Blobs"
    ),
    (
        make_classification(
            n_samples=n_samples,
            n_features=2,
            n_informative=2,
            n_redundant=0,
            n_clusters_per_class=1,
            n_classes=3,
            n_repeated=0,
            flip_y=0.1,
            class_sep=0.5,
            random_state=random_state
        ),
        "No Structure"
    ),
]

# Set up clustering algorithms
default_bandwidth = 0.3
connectivity = None  # Will be set per dataset

clustering_algorithms = [
    (
        "MiniBatchKMeans",
        cluster.MiniBatchKMeans(n_clusters=3)
    ),
    (
        "MeanShift",
        cluster.MeanShift(bandwidth=default_bandwidth, bin_seeding=True)
    ),
    (
        "AgglomerativeClustering",
        cluster.AgglomerativeClustering(n_clusters=3, linkage="ward")
    ),
    (
        "SpectralClustering",
        cluster.SpectralClustering(
            n_clusters=3, eigen_solver="arpack", affinity="nearest_neighbors", assign_labels="kmeans"
        )
    ),
    (
        "DBSCAN",
        cluster.DBSCAN(eps=0.3)
    ),
    (
        "OPTICS",
        cluster.OPTICS(min_samples=10, xi=0.05, min_cluster_size=0.1)
    ),
    (
        "AffinityPropagation",
        cluster.AffinityPropagation(damping=0.9, preference=-200)
    ),
    (
        "Birch",
        cluster.Birch(n_clusters=3)
    ),
    (
        "GaussianMixture",
        mixture.GaussianMixture(n_components=3, covariance_type="full")
    ),
]

if has_hdbscan:
    clustering_algorithms.append(
        ("HDBSCAN", hdbscan.HDBSCAN(min_cluster_size=15))
    )

plt.figure(figsize=(len(clustering_algorithms) * 3, len(datasets) * 3))
plt.subplots_adjust(left=.02, right=.98, bottom=.001, top=.96, wspace=.05, hspace=.2)

for i_dataset, (dataset, dataset_name) in enumerate(datasets):
    X, y = dataset
    X = StandardScaler().fit_transform(X)

    # Estimate bandwidth for MeanShift
    if "MeanShift" in [name for name, _ in clustering_algorithms]:
        from sklearn.cluster import estimate_bandwidth
        bandwidth = estimate_bandwidth(X, quantile=0.3)
        for idx, (name, algo) in enumerate(clustering_algorithms):
            if name == "MeanShift":
                clustering_algorithms[idx] = (
                    name,
                    cluster.MeanShift(bandwidth=bandwidth, bin_seeding=True)
                )

    # Compute connectivity matrix for structured Ward
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", message="kneighbors_graph")
        try:
            connectivity = kneighbors_graph(X, n_neighbors=10, include_self=False)
            # make connectivity symmetric
            connectivity = 0.5 * (connectivity + connectivity.T)
        except Exception:
            connectivity = None

    for i_algo, (name, algorithm) in enumerate(clustering_algorithms):
        t0 = time.time()
        params = {}

        # Some algorithms need special handling
        if name == "AgglomerativeClustering":
            params = {"connectivity": connectivity}
        elif name == "SpectralClustering":
            params = {"random_state": 42}
        elif name == "MiniBatchKMeans":
            params = {"random_state": 42}
        elif name == "GaussianMixture":
            params = {"random_state": 42}
        elif name == "Birch":
            params = {}
        elif name == "AffinityPropagation":
            params = {}
        elif name == "MeanShift":
            params = {}
        elif name == "DBSCAN":
            params = {}
        elif name == "OPTICS":
            params = {}
        elif name == "HDBSCAN":
            params = {}

        # Clone the algorithm to avoid fitting the same instance multiple times
        import copy
        algo = copy.deepcopy(algorithm)
        for k, v in params.items():
            setattr(algo, k, v)

        with warnings.catch_warnings():
            warnings.filterwarnings("ignore", category=UserWarning)
            try:
                if name == "GaussianMixture":
                    algo.fit(X)
                    y_pred = algo.predict(X)
                else:
                    algo.fit(X)
                    if hasattr(algo, "labels_"):
                        y_pred = algo.labels_.astype(int)
                    else:
                        y_pred = algo.predict(X)
            except Exception:
                y_pred = np.full(X.shape[0], -1)

        t1 = time.time()
        plt.subplot(len(datasets), len(clustering_algorithms), i_dataset * len(clustering_algorithms) + i_algo + 1)
        colors = np.array(
            [
                "#377eb8", "#ff7f00", "#4daf4a", "#f781bf", "#a65628",
                "#984ea3", "#999999", "#e41a1c", "#dede00"
            ]
        )
        # Handle outliers
        mask = y_pred == -1
        plt.scatter(X[~mask, 0], X[~mask, 1], s=10, color=colors[y_pred[~mask] % len(colors)])
        if np.any(mask):
            plt.scatter(X[mask, 0], X[mask, 1], s=10, color="k", alpha=0.3)
        plt.title(f"{name}\n{t1 - t0:.2f}s", size=10)
        plt.xticks([])
        plt.yticks([])
        if i_algo == 0:
            plt.ylabel(dataset_name, size=12)

plt.tight_layout()
plt.show()
